package components_test

import (
	"go/ast"
	"go/parser"
	"go/token"
	"io/fs"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"testing"
)

// The footer used to be written eight times over, once per view, and that is
// how the errors ended up left-aligned everywhere while the notices were
// centred: nobody ever centred the error branch, in any of the eight.
//
// These two tests read the sources the way internal/ui/keymap's do. A
// convention nothing verifies is exactly what produced the divergence.

// uiRoots are the trees a view can live in.
var uiRoots = []string{"../../ui", "../../app"}

// forbiddenInFooter are the styles that mean "I am rendering my own footer
// message". They have legitimate uses elsewhere — status icons, table rows,
// panels — so the ban is scoped to the functions that render the footer.
var forbiddenInFooter = []string{
	"StatusErrorStyle",
	"StatusOKStyle",
	"StatusWarningStyle",
	"ColorHighlight",
}

func TestNoViewStylesItsOwnFooterMessage(t *testing.T) {
	forEachUIFile(t, func(path string, file *ast.File, fset *token.FileSet) {
		// This package is the one implementation; it is allowed to style.
		if strings.Contains(filepath.ToSlash(path), "internal/ui/components/") {
			return
		}

		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Body == nil || !rendersFooter(fn.Name.Name) {
				continue
			}
			ast.Inspect(fn.Body, func(n ast.Node) bool {
				id, ok := n.(*ast.Ident)
				if !ok {
					return true
				}
				for _, banned := range forbiddenInFooter {
					if id.Name == banned {
						t.Errorf("%s: %s uses theme.%s to render a footer message.\n"+
							"The three levels live in components.FooterMessage — call m.footer.Info/Warn/Error "+
							"and render with m.footer.View(width, status).",
							fset.Position(id.Pos()), fn.Name.Name, banned)
					}
				}
				return true
			})
		}
	})
}

// rendersFooter reports whether a function's name says it draws the footer's
// message line. The three names cover every view: RenderFooter itself, and the
// two shapes the helper it delegates to has always taken.
func rendersFooter(name string) bool {
	switch {
	case strings.Contains(name, "RenderFooter"):
		return true
	case strings.Contains(name, "InfoLine"), strings.Contains(name, "InfoText"):
		return true
	default:
		return false
	}
}

// A table's load belongs to the footer, with a spinner, so the table itself
// stays on screen — a body that swaps itself for a spinner loses its header and
// its columns for the length of every refresh.
//
// theme.SpinnerMessage is what those bodies called; it is being removed
// (DEVDESK-377) and no body may name it.
var viewsWithATableBody = []string{
	"containers/view.go",
	"oci_resources/view.go",
	"oci_resources/browser_view.go",
	// forge/, not gitlab/: the package moved with §3.6 and this entry did not,
	// so the explorer went unguarded until the signed-out body was moved to the
	// footer and the stale suffix turned up.
	"forge/explorer/view.go",
	"status/view.go",
	"viewer/view.go",
	// netdiag has four bodies, one per tab plus the dispatcher. The single
	// entry that used to stand for this package named topology_model.go, which
	// §3.44 deleted — so the package went unguarded, exactly the way the
	// explorer did above. TestEveryGuardedFileExists is what stops a third.
	"netdiag/view.go",
	"netdiag/ports_model.go",
	"netdiag/interfaces_model.go",
	"netdiag/forward_model.go",
	// The sessions table of :agent-usage; its load belongs to the footer.
	"agentusageview/view.go",
}

// TestEveryGuardedFileExists rejects a suffix in viewsWithATableBody that
// matches nothing.
//
// The guard above works by suffix, so an entry naming a file that has been
// renamed or deleted does not fail — it silently guards nothing, and the view
// it was written for is unprotected from then on. That has already happened
// twice: forge/explorer/view.go after §3.6 renamed the package, and
// netdiag/topology_model.go after §3.44 deleted the file. Both were found by
// accident, a long way after the fact.
func TestEveryGuardedFileExists(t *testing.T) {
	matched := make(map[string]bool, len(viewsWithATableBody))
	forEachUIFile(t, func(path string, _ *ast.File, _ *token.FileSet) {
		slash := filepath.ToSlash(path)
		for _, suffix := range viewsWithATableBody {
			if strings.HasSuffix(slash, suffix) {
				matched[suffix] = true
			}
		}
	})
	for _, suffix := range viewsWithATableBody {
		if !matched[suffix] {
			t.Errorf("viewsWithATableBody names %q, which matches no file under internal/ui.\n"+
				"It guards nothing: either the file was renamed or deleted, and the entry has to "+
				"follow it or go.", suffix)
		}
	}
}

func TestNoTableViewRendersALoadingBody(t *testing.T) {
	forEachUIFile(t, func(path string, file *ast.File, fset *token.FileSet) {
		slash := filepath.ToSlash(path)
		guarded := false
		for _, suffix := range viewsWithATableBody {
			if strings.HasSuffix(slash, suffix) {
				guarded = true
				break
			}
		}
		if !guarded {
			return
		}

		inspect := func(fn string, body ast.Node) {
			ast.Inspect(body, func(n ast.Node) bool {
				sel, ok := n.(*ast.SelectorExpr)
				if !ok || sel.Sel.Name != "SpinnerMessage" {
					return true
				}
				t.Errorf("%s: %s renders a spinner in the body of a table view.\n"+
					"A load is reported in the footer: return components.Status{Text: …, Activity: true} "+
					"from the view's status() "+
					"and leave the table on screen.",
					fset.Position(sel.Pos()), fn)
				return true
			})
		}

		for _, decl := range file.Decls {
			fn, ok := decl.(*ast.FuncDecl)
			if !ok || fn.Body == nil {
				continue
			}
			inspect(fn.Name.Name, fn.Body)
		}
	})
}

// rowPhrases are the pieces of a row-activity sentence that only
// components.DescribeRow (row_activity.go), DescribeRun and DescribeItem
// (job_activity.go) may spell: the footer sentence for a
// row ("Queued: scan x", "x: last scan failed — cause", "(+1 earlier failure)").
// A view that writes one itself would drift from the activity column, which is
// what the single computation exists to prevent.
//
// Deliberately NOT banned: the bare verbs ("Scanning", "Cloning", ...), which
// views legitimately use as progress titles and fuzzy-finder prompts, and
// "Failed to <verb>", which several views still write themselves
// (explorer/create.go, explorer/clone.go, templates/update.go, app/context.go).
// Their migration stories move them to components.FailureEvent, and the ban
// can be added then.
var rowPhrases = []*regexp.Regexp{
	regexp.MustCompile(`earlier failure`),
	regexp.MustCompile(`Queued: `),
	regexp.MustCompile(`: last `),
	regexp.MustCompile(` was cancelled`),
	regexp.MustCompile(`(?i)\blast [a-z]+ failed\b`),
}

// declaredRowPhraseExceptions maps a file suffix to the reason a string literal
// there may contain a row phrase. Empty today: no view spells one.
var declaredRowPhraseExceptions = map[string]string{}

func TestNoViewSpellsARowActivityPhrase(t *testing.T) {
	forEachUIFile(t, func(path string, file *ast.File, fset *token.FileSet) {
		slash := filepath.ToSlash(path)
		// The one implementation, and the shared component package around it.
		// The walker yields paths relative to this package ("../../ui/..."),
		// hence no "internal/" prefix.
		if strings.Contains(slash, "/ui/components/") {
			return
		}
		for suffix := range declaredRowPhraseExceptions {
			if strings.HasSuffix(slash, suffix) {
				return
			}
		}
		ast.Inspect(file, func(n ast.Node) bool {
			lit, ok := n.(*ast.BasicLit)
			if !ok || lit.Kind != token.STRING {
				return true
			}
			text, err := strconv.Unquote(lit.Value)
			if err != nil {
				text = lit.Value
			}
			for _, re := range rowPhrases {
				if re.MatchString(text) {
					t.Errorf("%s: string literal %s spells a row-activity phrase (%s).\n"+
						"A row's sentence is built by components.DescribeRow and a failure event by "+
						"components.FailureEvent; call them instead of writing the words.",
						fset.Position(lit.Pos()), lit.Value, re)
				}
			}
			return true
		})
	})
}

// forEachUIFile parses every non-test .go file under the UI trees.
func forEachUIFile(t *testing.T, visit func(path string, file *ast.File, fset *token.FileSet)) {
	t.Helper()

	seen := map[string]bool{}
	for _, root := range uiRoots {
		err := filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}
			if d.IsDir() || !strings.HasSuffix(path, ".go") || strings.HasSuffix(path, "_test.go") {
				return nil
			}
			abs, err := filepath.Abs(path)
			if err != nil {
				return err
			}
			if seen[abs] {
				return nil
			}
			seen[abs] = true

			fset := token.NewFileSet()
			file, err := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
			if err != nil {
				t.Fatalf("parse %s: %v", path, err)
			}
			visit(path, file, fset)
			return nil
		})
		if err != nil {
			t.Fatalf("walk %s: %v", root, err)
		}
	}
	if len(seen) == 0 {
		t.Fatal("no sources were scanned; the guard would pass on an empty set")
	}
}

package ociresources

import (
	"strings"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// rebuildTagTable re-decorates the rows and hands them to the table.
//
// The decoration — the scan counts, whether a scan is running, the registry's
// label — is not on the tag, and the columns are built once so they cannot
// reach the browser for it. So it is recomputed wholesale on every change,
// exactly as the images tab does with imageRow.
//
// The filters are applied here because they narrow the tags before the table
// sees them; the sort and the header arrows are the table's.
func (b *RegistryBrowser) rebuildTagTable() {
	tags := b.filteredMultiTags()

	rows := make([]tagRow, len(tags))
	for i, t := range tags {
		imageName := multiImageName(t.RegistryURL, t.Repo, t.Tag)
		label := t.Alias
		if label == "" {
			label = t.RegistryURL
		}
		entry, scanned := b.scanCache[imageName]
		rows[i] = tagRow{
			tag:         t,
			label:       label,
			entry:       entry,
			scanned:     scanned,
			Activity:    b.tagActivity(imageName),
			ScanRunning: b.scanRunning(imageName),
		}
	}

	b.tagTable.SetItems(rows)
	b.resizeTagTable()
}

// tagActivity resolves what one tag row says about its activity: a scan or a
// pull, whoever started it, or a remembered failure of either. Both are read
// against the context the snapshot carries, with the raw reference as identity.
func (b *RegistryBrowser) tagActivity(imageName string) components.RowActivity {
	return components.DescribeRow(components.RowQuery{
		Runs: b.jobs, Failures: b.failures, Context: b.contextName,
		Target: jobs.TargetKey(imageName), Kinds: ociKinds,
	})
}

// scanRunning reports whether a scan of the tag runs now. A queued scan does
// not: it keeps its counts.
func (b *RegistryBrowser) scanRunning(imageName string) bool {
	for _, a := range jobs.ActiveOn(b.jobs, b.contextName, imageName, jobs.KindScan) {
		if a.Item.State == jobs.ItemRunning {
			return true
		}
	}
	return false
}

// View renders the browser for the current state.
func (b *RegistryBrowser) View() string {
	switch b.state {
	case browserStateTags:
		return b.viewTags()
	default:
		return b.viewInput()
	}
}

func (b *RegistryBrowser) viewInput() string {
	var sb strings.Builder

	sb.WriteString(theme.EmptyLineBg(b.width) + "\n")
	sb.WriteString(b.renderInputField("Repository", b.repoInput.View(), brFieldRepo))
	sb.WriteString("\n\n")

	if len(b.rows) > 0 {
		sb.WriteString(theme.Bg("  ") + theme.DimStyle.Render("Registries:") + "\n")
		for i, row := range b.rows {
			focused := b.focusedField == b.brFieldReg(i)
			if row.groupSlug != "" {
				// One checkbox for the whole group, with a third state for a
				// partial selection — eight proxies are not eight keystrokes.
				sb.WriteString(theme.RenderCheckboxTri(b.groupState(row.groupSlug), row.label, focused))
			} else {
				sb.WriteString(theme.RenderCheckbox(b.selected(b.entries[row.entry]), row.label, focused))
			}
			if i < len(b.rows)-1 {
				sb.WriteString("\n")
			}
		}
		sb.WriteString("\n\n")
	}

	sb.WriteString("  ")
	sb.WriteString(theme.RenderButton("Browse Tags", b.focusedField == b.brFieldSubmit(), "primary"))

	return sb.String()
}

func (b *RegistryBrowser) renderInputField(label, value string, fieldIdx int) string {
	var labelStr string
	if b.focusedField == fieldIdx {
		labelStr = theme.KeyStyle.Render(theme.IconCircleSmall + " " + label + " " + theme.IconChevronRight)
	} else {
		labelStr = theme.Bg("  " + label + " " + theme.IconChevronRight)
	}
	return labelStr + "\n  " + value
}

// viewTags renders the tag table. The search says so in the footer, with the
// shared activity dot (LoadingLabel), and an empty table stays a table (Rule 139) — the
// count lives in GetHeaderInfo's "Tags" field.
func (b *RegistryBrowser) viewTags() string {
	return b.tagTable.View()
}

// LoadingLabel names what the browser is fetching, for the OCI view's footer.
// The second result is false when nothing is in flight.
func (b *RegistryBrowser) LoadingLabel() (string, bool) {
	if b.state == browserStateTags && b.pendingSearches > 0 {
		return "Searching registries...", true
	}
	return "", false
}

// FilterIsVisible returns true when the tag filter bar should be shown in the footer.
func (b *RegistryBrowser) FilterIsVisible() bool {
	return b.state == browserStateTags && (b.filterActive || b.filterInput.Value() != "" || !b.registryFilter.isEmpty())
}

// FilterBarView renders the filter bar (2 lines) for display in the footer.
func (b *RegistryBrowser) FilterBarView(width int) string {
	borderStyle := lipgloss.NewStyle().Foreground(theme.ColorViewportBorder).Background(theme.ColorBackground)

	var left string
	if b.filterActive {
		left = theme.KeyStyle.Render("/") + theme.Bg(" ") + b.filterInput.View()
	} else if b.filterInput.Value() != "" {
		left = theme.DimStyle.Render("/ ") + theme.KeyStyle.Render(b.filterInput.Value())
	} else {
		left = theme.DimStyle.Render("/ filter…")
	}

	if !b.registryFilter.isEmpty() {
		left += theme.Bg("  ") + theme.KeyStyle.Render("["+b.registryFilterLabel()+"]")
	}

	inner := theme.Bg(" ") + left
	paddedInner := theme.PadWithBg(inner, width-2)
	contentLine := borderStyle.Render("│") + paddedInner + borderStyle.Render("│")
	bottomBorder := borderStyle.Render("└" + strings.Repeat("─", width-2) + "┘")
	return contentLine + "\n" + bottomBorder
}

